import java.io.InputStream;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.Arrays;

public class Main {

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int head = 0;
        private int tail = 0;

        public FastScanner(InputStream in) {
            this.in = in;
        }

        private int read() throws IOException {
            if (head >= tail) {
                head = 0;
                tail = in.read(buffer, 0, buffer.length);
                if (tail <= 0) return -1;
            }
            return buffer[head++];
        }

        public int nextInt() throws IOException {
            int c = read();
            while (c <= ' ') {
                if (c == -1) return -1;
                c = read();
            }
            int res = 0;
            while (c > ' ') {
                if (c < '0' || c > '9') {
                    throw new NumberFormatException();
                }
                res = res * 10 + (c - '0');
                c = read();
            }
            return res;
        }
    }

    static int N, M;
    static int[] head, to, next;
    static int edgeCount = 0;

    // Listas de adjacência ordenadas representadas de forma compacta
    static int[] adjHead, adjTo, adjNext;
    static int adjEdgeCount = 0;

    // Arrays para a representação flattened dos vizinhos
    static int[] deg;
    static int[] offset;
    static int[] sortedNeighbors;

    // DP memoization
    // dpEdge[e] memoriza dp(u, v) para o arco de índice e
    // fTable[offset[v] + k] memoriza f(v, k)
    static int[] dpEdge;
    static int[] fTable;

    static void addEdge(int u, int v) {
        to[edgeCount] = v;
        next[edgeCount] = head[u];
        head[u] = edgeCount++;
    }

    // Busca binária para encontrar o menor k tal que sortedNeighbors[offset[v] + k] > u
    static int findFirstGreater(int v, int u) {
        int low = 0, high = deg[v] - 1;
        int ans = deg[v];
        int base = offset[v];
        while (low <= high) {
            int mid = (low + high) >>> 1;
            if (sortedNeighbors[base + mid] > u) {
                ans = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return ans;
    }

    // f(v, k): maior caminho a partir de v escolhendo algum vizinho entre k e deg[v]-1
    static int getF(int v, int k) {
        if (k >= deg[v]) return 1; // nenhum vizinho maior, tamanho do caminho restante é 1 (apenas o vértice v)
        int idx = offset[v] + k;
        if (fTable[idx] != 0) return fTable[idx];

        int w = sortedNeighbors[idx];
        // Encontra o id da aresta (v, w)
        int e = findEdge(v, w);

        int take = getDp(e);
        int skip = getF(v, k + 1);

        return fTable[idx] = Math.max(take, skip);
    }

    // dpEdge[e]: comprimento do caminho começando com o arco e (u -> v)
    static int getDp(int e) {
        if (dpEdge[e] != 0) return dpEdge[e];

        int u = to[e ^ 1]; // vértice de origem
        int v = to[e];     // vértice de destino

        int k = findFirstGreater(v, u);
        int bestNext = getF(v, k);

        return dpEdge[e] = 1 + bestNext;
    }

    // Busca binária na lista de arestas para encontrar o ID da aresta direcionada (u, v)
    static int[] edgeIds; // edgeIds[offset[u] + k] = índice da aresta u -> sortedNeighbors[...]

    static int findEdge(int u, int v) {
        int low = 0, high = deg[u] - 1;
        int base = offset[u];
        while (low <= high) {
            int mid = (low + high) >>> 1;
            int val = sortedNeighbors[base + mid];
            if (val == v) {
                return edgeIds[base + mid];
            } else if (val < v) {
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return -1;
    }

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner(System.in);
        N = scanner.nextInt();
        M = scanner.nextInt();

        deg = new int[N + 1];
        int[] uEdges = new int[M];
        int[] vEdges = new int[M];

        for (int i = 0; i < M; i++) {
            uEdges[i] = scanner.nextInt();
            vEdges[i] = scanner.nextInt();
            deg[uEdges[i]]++;
            deg[vEdges[i]]++;
        }

        offset = new int[N + 2];
        for (int i = 1; i <= N; i++) {
            offset[i + 1] = offset[i] + deg[i];
        }

        sortedNeighbors = new int[2 * M];
        edgeIds = new int[2 * M];
        fTable = new int[2 * M + 1];
        dpEdge = new int[2 * M];

        // Construir listas de vizinhos
        int[] curPos = offset.clone();
        for (int i = 0; i < M; i++) {
            int u = uEdges[i];
            int v = vEdges[i];
            sortedNeighbors[curPos[u]++] = v;
            sortedNeighbors[curPos[v]++] = u;
        }

        // Ordenar os vizinhos de cada vértice
        for (int i = 1; i <= N; i++) {
            int start = offset[i];
            int end = offset[i + 1];
            Arrays.sort(sortedNeighbors, start, end);
        }

        head = new int[N + 1];
        Arrays.fill(head, -1);
        to = new int[2 * M];
        next = new int[2 * M];

        // Adiciona as arestas de forma que e e e^1 correspondam a sentidos opostos
        for (int i = 0; i < M; i++) {
            int u = uEdges[i];
            int v = vEdges[i];
            addEdge(u, v);
            addEdge(v, u);
        }

        // Mapear cada vizinho ordenado para seu índice de aresta (u -> v)
        for (int e = 0; e < 2 * M; e++) {
            int u = to[e ^ 1];
            int v = to[e];
            int low = 0, high = deg[u] - 1;
            int base = offset[u];
            while (low <= high) {
                int mid = (low + high) >>> 1;
                int val = sortedNeighbors[base + mid];
                if (val == v) {
                    edgeIds[base + mid] = e;
                    break;
                } else if (val < v) {
                    low = mid + 1;
                } else {
                    high = mid - 1;
                }
            }
        }

        // Calcular a resposta para cada nó i
        PrintWriter out = new PrintWriter(System.out);
        StringBuilder sb = new StringBuilder();

        for (int i = 1; i <= N; i++) {
            int ans = 1; // caminho de tamanho 1 contendo apenas o nó i
            for (int k = 0; k < deg[i]; k++) {
                int e = edgeIds[offset[i] + k];
                ans = Math.max(ans, getDp(e));
            }
            sb.append(ans);
            if (i < N) sb.append(' ');
        }

        out.println(sb.toString());
        out.flush();
    }
}
